}

function execute(IERC20Token _token, bytes memory _data) private {
uint256[1] memory ret = [uint256(1)];

assembly {
let success := call(
gas,
_token,
0,
add(_data, 32),
mload(_data),
ret,
32
)
if iszero(success) {
revert(0, 0)
}
}

require(ret[0] != 0, "ERR_TRANSFER_FAILED");
}
}

